import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.B5WAEDB7.js";const g=JSON.parse(`{"title":"Setting up the Team Space","description":"Mark a Space as a Team Space, assign Keys, and set the app's branding.","frontmatter":{"title":"Setting up the Team Space","description":"Mark a Space as a Team Space, assign Keys, and set the app's branding."},"headers":[],"relativePath":"en/apptiveteams/team-space.md","filePath":"en/apptiveteams/team-space.md","lastUpdated":1787319236000}`),s={name:"en/apptiveteams/team-space.md"};function r(n,e,d,c,h,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="setting-up-the-team-space" tabindex="-1">Setting up the Team Space <a class="header-anchor" href="#setting-up-the-team-space" aria-label="Permalink to &quot;Setting up the Team Space&quot;">​</a></h1><p>A <strong>Team Space</strong> is a perfectly normal ApptiveGrid Space — with two special traits: it carries the category <code>apptiveTeams</code>, and its configuration Grids are discoverable by <strong>Keys</strong>.</p><h2 id="marking-a-space-as-a-team-space" tabindex="-1">Marking a Space as a Team Space <a class="header-anchor" href="#marking-a-space-as-a-team-space" aria-label="Permalink to &quot;Marking a Space as a Team Space&quot;">​</a></h2><p>In the Space settings, set the <strong>category</strong> to <code>apptiveTeams</code>.</p><div class="warning custom-block"><p class="custom-block-title">Without this category, the Space won&#39;t appear in the app</p><p>The app only offers Spaces with the category <code>apptiveTeams</code> for selection. If someone sees &quot;no team,&quot; that&#39;s the first thing to check — the second is whether they&#39;re even a member of the Space.</p></div><p>→ <a href="/en/spaces/symbol-und-farbe">Icon, color, and category</a></p><h2 id="keys-how-the-app-finds-its-grids" tabindex="-1">Keys: how the app finds its Grids <a class="header-anchor" href="#keys-how-the-app-finds-its-grids" aria-label="Permalink to &quot;Keys: how the app finds its Grids&quot;">​</a></h2><p>A <strong>Key</strong> is a readable identifier that Grids and fields can carry in addition to their name. The interface explains it like this:</p><blockquote><p><em>A Key is a readable identifier for this Grid. It can be used to connect a Grid to an app.</em></p></blockquote><p>That&#39;s exactly what ApptiveTeams uses. The app doesn&#39;t look for Grids named &quot;Configuration&quot; or &quot;Tabs&quot; — it looks for Grids with the Keys <code>config</code>, <code>tabs</code>, and <code>settings</code>. You&#39;re free to name them however you like, and to rename them at any time.</p><table tabindex="0"><thead><tr><th>What</th><th>Where you set the Key</th></tr></thead><tbody><tr><td><strong>Grid</strong></td><td>Grid menu (⋮) → <strong>Manage Grid Key</strong></td></tr><tr><td><strong>Fields</strong></td><td>View menu (⋮) → <strong>Manage Field Keys</strong></td></tr><tr><td>Individual field</td><td>Column menu → <strong>Change column Key</strong></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Keys must be written exactly</p><p>Case matters. <code>primarycolor</code> is not <code>primaryColor</code>, and an accidental space makes a Key unusable. A faulty Key doesn&#39;t show up as an error message — content simply goes missing in the app.</p></div><h2 id="the-three-configuration-grids" tabindex="-1">The three configuration Grids <a class="header-anchor" href="#the-three-configuration-grids" aria-label="Permalink to &quot;The three configuration Grids&quot;">​</a></h2><p>Inside the Team Space, the app expects three Grids:</p><table tabindex="0"><thead><tr><th>Grid Key</th><th>Purpose</th></tr></thead><tbody><tr><td><code>config</code></td><td>The app&#39;s branding: logo, primary color, version</td></tr><tr><td><code>tabs</code></td><td>The tabs in the bottom navigation bar</td></tr><tr><td><code>settings</code></td><td>Additional entries on the settings screen</td></tr></tbody></table><p>On top of that come the <strong>content Grids</strong> linked from the tabs — one Grid per tile or card tab. These don&#39;t need a Grid Key, since they&#39;re found through a link. → <a href="/en/apptiveteams/tabs">Set up tabs</a></p><div class="tip custom-block"><p class="custom-block-title">Views work too</p><p>As a configuration Grid, you can use either a regular Grid or a <strong>View</strong>. If the app finds both with the same Key, the View wins.</p><p>That&#39;s useful: a filtered View lets you hide content without deleting it — for example, news items with a <code>Published</code> checkmark.</p></div><h2 id="setting-branding-the-config-grid" tabindex="-1">Setting branding: the <code>config</code> Grid <a class="header-anchor" href="#setting-branding-the-config-grid" aria-label="Permalink to &quot;Setting branding: the `config` Grid&quot;">​</a></h2><p>The Grid with the Key <code>config</code> controls the app&#39;s appearance. Only the <strong>first row</strong> is evaluated.</p><table tabindex="0"><thead><tr><th>Field Key</th><th>Field type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>logo</code></td><td>Files (Image)</td><td>yes</td><td>Your company&#39;s logo, shown e.g. above the Tile view</td></tr><tr><td><code>primaryColor</code></td><td>Text</td><td>yes</td><td>Primary color as a hex value, e.g. <code>#1565C0</code>. Colors icons, buttons, and the active tab indicator</td></tr><tr><td><code>version</code></td><td>Text / Number</td><td>no</td><td>Version of the Team Space schema. Currently <code>1</code>; assumed to be <code>1</code> if left blank</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">If the logo or color is missing, no branding is applied at all</p><p>The app only evaluates the configuration row if <strong>both</strong> required fields are filled in. If one is missing, the entire row is discarded — the app then starts with no logo <em>and</em> no color, not just without the missing piece.</p><p>The color must be a hex value. A color name like <code>blue</code> doesn&#39;t work.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/apptiveteams/tabs">Set up tabs</a></li><li><a href="/en/apptiveteams/einstellungen">Add to the settings screen</a></li><li><a href="/en/apptiveteams/fehlerbehebung">Tips and troubleshooting</a></li></ul>',23)])])}const m=t(s,[["render",r]]);export{g as __pageData,m as default};
